-- Additive migration. Run once through the authorized Supabase SQL editor.
-- Public signup does NOT grant workspace access: membership must be added by an administrator.
create table if not exists public.hyopu_members (
  user_id uuid primary key references auth.users(id) on delete cascade,
  pic text check (pic in ('DENNIS','JAE LEE','JACK','RICK')),
  role text not null default 'editor' check (role in ('editor','viewer')),
  created_at timestamptz not null default now()
);
create table if not exists public.hyopu_port_calls (
  id text primary key,
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  revision integer not null default 1 check (revision > 0),
  updated_by uuid references auth.users(id),
  updated_at timestamptz not null default now()
);
alter table public.hyopu_members enable row level security;
alter table public.hyopu_port_calls enable row level security;
revoke all on public.hyopu_members, public.hyopu_port_calls from anon, authenticated;
grant all on public.hyopu_members, public.hyopu_port_calls to service_role;
-- No browser/anonymous policies. API verifies Auth user + membership before every read/write.
-- Conditional PATCH by primary key AND revision prevents silent concurrent overwrite.
on conflict (id) do nothing;
-- Invite staff in Supabase Authentication, then add their UUID in hyopu_members.
-- Never paste passwords or service keys into source control or a public message.
